/* Table formatting inside the chat bubble */
.ai-table-container {
  width: 100%;
  overflow-x: auto;
  margin: 8px 0;
  border-radius: 6px;
  border: 1px solid var(--modal-border);
}

.ai-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  white-space: nowrap;
}

.ai-table th,
.ai-table td {
  border: 1px solid var(--modal-border);
  padding: 6px 10px;
  text-align: left;
}

.ai-table th {
  background-color: var(--control-bg);
  font-weight: 600;
  color: var(--modal-text);
}

.ai-table tr:nth-child(even) {
  background-color: var(--control-bg);
}

/* Feedback buttons */
.ai-feedback-row {
  display: flex;
  gap: 6px;
  margin-top: 4px;
  padding: 0 2px;
  opacity: 0;
  transition: opacity .15s;
}
.ai-msg-row.bot:hover .ai-feedback-row { opacity: 1; }
.ai-feedback-row.voted { opacity: 1; }
.ai-feedback-btn {
  background: none;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 6px;
  padding: 3px 7px;
  font-size: 12px;
  cursor: pointer;
  color: #c9a227;
  line-height: 0;
  transition: color .15s, border-color .15s;
}
.ai-feedback-btn:hover:not(:disabled) { color: #f9c74f; border-color: #f9c74f; }
.ai-feedback-btn.active { color: #f9c74f; border-color: #f9c74f; }
.ai-feedback-btn:disabled { cursor: default; opacity: 0.5; }
.ai-cached-badge {
  font-size: 10px;

