    .replace(/### (.+)/g, '<h3 style="margin: 20px 0 10px 0; font-size: 16px; font-weight: 700;">$1</h3>')
    .replace(/## (.+)/g, '<h2 style="margin: 24px 0 12px 0; font-size: 18px; font-weight: 700;">$1</h2>')
    .replace(/# (.+)/g, '<h1 style="margin: 28px 0 14px 0; font-size: 20px; font-weight: 700;">$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/`([^`]+)`/g, '<code style="background: var(--control-bg); padding: 2px 5px; border-radius: 4px; font-size: 0.9em;">$1</code>')
    .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" target="_blank">$1</a>');

  // Robust Markdown Table parser
  // We match from the first pipe to the last pipe in a greedy block
  html = html.replace(/((^|\n)\|[\s\S]*?\|($|\n(?![| \t]*\|)))/g, function (match) {
    let rows = match.trim().split('\n').map(r => r.trim()).filter(r => r.length > 0);
    if (rows.length < 2) return match;

    let bodyRows = [];

    rows.forEach((row) => {
      if (row.match(/^\|?[\s|:-]+\|?$/)) return; // separator row

      let cols = row.split('|');
      // Remove leading/trailing empty cells if pipes were used as borders
      if (row.startsWith('|')) cols.shift();
      if (row.endsWith('|')) cols.pop();
      bodyRows.push(cols.map(c => c.trim()));
    });

    // Store table data for export
    const headers = bodyRows[0] || [];
    const dataRows = bodyRows.slice(1) || [];

    let out = '<div class="ai-table-container">';

    // Add download button if enabled
    if (enableTableDownload && dataRows.length > 0) {
      out += '<div class="table-download-bar">';
      out += '<button class="table-download-btn" title="Download table as CSV">';
      out += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg>';
      out += ' Download Table';
      out += '</button>';
      out += '<span class="table-rows-info">' + dataRows.length + ' rows</span>';
      out += '</div>';
      // Store table data in a script tag for later retrieval
      out += '<script type="application/json" class="table-data">';
      out += JSON.stringify({ headers: headers, rows: dataRows });
      out += '<\/script>';
    }

    out += '<table class="ai-table">';

    bodyRows.forEach((cols, rowIndex) => {
      out += '<tr>';
      cols.forEach(col => {
        if (rowIndex === 0) {
          out += `<th>${col}</th>`;
        } else {
          out += `<td>${col}</td>`;
        }
      });
      out += '</tr>';
    });

    out += '</table></div>';
    return out;
  });

