  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');

  // Horizontal rules
  html = html.replace(/^---+$/gm, '<hr>');

  // Tables (simple approach - detect table rows)
  html = html.replace(/^\|(.+)\|$/gm, function(match, content) {
    const cells = content.split('|').map(c => c.trim());
    const cellTags = cells.map(c => {
      // Check if this is a separator row (--|---|---)
      if (/^:?-+:?$/.test(c)) return null;
      return `<td>${c}</td>`;
    }).filter(Boolean);
    if (cellTags.length === 0) return '';
    return '<tr>' + cellTags.join('') + '</tr>';
  });
  // Wrap table rows in table tags
  html = html.replace(/(<tr>.+<\/tr>\n?)+/g, '<table>$&</table>');

  // Unordered lists (lines starting with - or *)
  html = html.replace(/^[*-] (.+)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>.+<\/li>\n?)+/g, '<ul>$&</ul>');

  // Ordered lists (lines starting with 1., 2., etc)
  html = html.replace(/^\d+\. (.+)$/gm, '<li>$1</li>');

  // Bold: **text** or __text__
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');

  // Italic: *text* or _text_
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
  html = html.replace(/_(.+?)_/g, '<em>$1</em>');

  // Inline code: `code`
  html = html.replace(/`(.+?)`/g, '<code>$1</code>');

  // Links: [text](url) - do this BEFORE auto-linking plain URLs
  html = html.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');

  // Auto-link plain URLs (but not ones already in <a> tags)
  html = html.replace(/(^|[^"'>])(https?:\/\/[^\s<]+)/g, function(match, prefix, url) {
    // Don't link if it's already inside an href attribute
    return prefix + '<a href="' + url + '" target="_blank" rel="noopener">' + url + '</a>';
  });

  // Line breaks: preserve newlines, but not after block elements or between table rows
  html = html.replace(/\n/g, (match, offset, string) => {
    // Don't add <br> after closing block tags
    const beforeContext = string.substring(Math.max(0, offset - 50), offset);
    if (/<\/(table|ul|h[123]|tr)>\s*$/.test(beforeContext)) return '';
    // Don't add <br> before opening table rows
    const afterContext = string.substring(offset + 1, Math.min(string.length, offset + 10));
    if (/^\s*<tr>/.test(afterContext)) return '';
    return '<br>';
  });

  return html;
}

function addMessage(role, text, cls) {
  if (introEl) introEl.style.display = 'none';

  const msg    = document.createElement('div');
  msg.className = `msg ${role}`;

  const avatar = document.createElement('div');
  avatar.className = 'avatar';
  if (role === 'user') {
    avatar.textContent = '👤';
  } else {
    const img = document.createElement('img');
    img.src = 'safecast-square-ct.png';
    img.alt = 'Safecast';
    avatar.appendChild(img);
  }

  const bubble = document.createElement('div');
  bubble.className = `bubble ${cls || ''}`;
  // User messages are plain text, bot messages support markdown
  if (role === 'bot') {
    bubble.innerHTML = markdownToHTML(text);

    // Add copy button for bot messages
    const copyBtn = document.createElement('button');
    copyBtn.className = 'copy-btn';
    copyBtn.textContent = 'Copy';
    copyBtn.onclick = () => copyMessage(text, copyBtn);
    bubble.appendChild(copyBtn);
  } else {
    bubble.textContent = text;
  }

  msg.appendChild(avatar);

